(() => {
const PLAN = window.PLAN;
const $ = (selector) => document.querySelector(selector);
const esc = (value) => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const badge = (text, color = 'violet') => `<span class="badge ${color}">${esc(text)}</span>`;
const icon = (kind = 'home') => {
  const paths = {home:'M3 10l9-7 9 7v10H3z M9 20v-7h6v7',calendar:'M4 5h16v16H4z M8 3v4 M16 3v4 M4 10h16',chat:'M4 4h16v12H9l-5 4z',user:'M8 7a4 4 0 1 0 8 0a4 4 0 1 0-8 0 M4 22v-3a8 8 0 0 1 16 0v3',file:'M6 3h8l4 4v14H6z M14 3v5h4 M9 12h6 M9 16h6',check:'M5 12l4 4L19 6'};
  return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[kind] || paths.file}"/></svg>`;
};
let workerScreen = 'home', opsTab = 'note', scenario = 'reported';
let state;
let toastTimer;
function loadScenario(name) {
  scenario = name;
  state = {workerName:'Maria Rodriguez', caseId:'MC-1042', kind:'injury', status:'reported', expectedDate:'2026-10-20', document:false, fileName:'medical-note.pdf', clearanceType:'FULL', otherCase:false, accountRestricted:false, consent:false, notices:[], claimStatus:'Not filed', carrier:'', claimNumber:'', claimFiledAt:'', rejectedReason:'', reviewDecision:'', impacts:[{label:'Fri, Oct 9 · 6a–2p', role:'Picker / packer', status:'Cancelled'}, {label:'Mon, Oct 12 · 6a–2p',role:'Picker / packer',status:'Needs Ops review'}, {label:'Tue, Oct 20 · 6a–2p',role:'Picker / packer',status:'Needs Ops review'}], events:[['Injury case opened','Oct 8, 9:20a · Neutron'],['Oct 9 shift cancelled · Medical exemption applied','Oct 8, 9:21a · System']], cancelPending:false, exemptionPending:false, visitDate:'2026-10-08', restrictions:[]};
  if (['restricted','review','cleared','multiple','suspended'].includes(name)) {
    state.document = true;
    state.status = name === 'restricted' ? 'restricted' : 'review';
    state.clearanceType = name === 'restricted' ? 'RESTRICTED' : 'FULL';
    if(name==='restricted')state.restrictions=['Lifting limit: 20 lbs','No ladders or heights'];
    state.impacts.forEach(s => s.status = 'Cancelled');
    state.events.push([name === 'restricted' ? 'Restricted note received · Check-in Oct 20' : 'Full-clearance note submitted · Ops review due Oct 9', 'Oct 8, 10:15a · Worker']);
  }
  if (name === 'cleared') {
    state.status = 'cleared'; state.reviewDecision = 'Approved';
    state.events.unshift(['Case cleared and customer notice sent','Oct 8, 11:05a · Ops']);
    state.notices.push({kind:'clearance', workerName:state.workerName, date:'Oct 8, 2026', sentAt:'Oct 8, 11:05a', documentOnFile:false});
  }
  if (name === 'multiple') state.otherCase = true;
  if (name === 'suspended') state.accountRestricted = true;
  if (name === 'illness') {
    state.kind = 'illness'; state.status = 'illness'; state.document = false; state.caseId = 'MC-1048';
    state.events = [['Sickness cancellation confirmed','Oct 8, 9:20a · Worker']];
    state.impacts = [{label:'Fri, Oct 9 · 6a–2p',role:'Picker / packer',status:'Cancelled'},{label:'Mon, Oct 12 · 6a–2p',role:'Picker / packer',status:'Booked'},{label:'Tue, Oct 20 · 6a–2p',role:'Picker / packer',status:'Booked'}];
  }
  workerScreen = name === 'illness' ? 'sick' : 'home'; opsTab = 'note';
  $('#scenario').value = name; render();
}
function hasHold() { return state.otherCase || (state.kind === 'injury' && !['cleared','voided'].includes(state.status)); }
function canBook() { return !hasHold() && !state.accountRestricted; }
function statusLabel() { return ({reported:'Awaiting note',restricted:'Recovering',review:'Pending review',cleared:'Cleared',illness:'Illness · Open',voided:'Voided'})[state.status]; }
function shortDate(iso = state.expectedDate) { if (!iso) return 'Not yet known'; return new Date(iso+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:'America/New_York'}); }
function holdCopy() { if(state.otherCase) return 'Another injury case is still open'; if(hasHold()) return 'Waiting for medical clearance'; if(state.accountRestricted) return 'Another account restriction remains'; return 'Booking available'; }
function toast(message) { $('#toast').textContent = message; $('#toast').style.display = 'block'; clearTimeout(toastTimer); toastTimer = setTimeout(()=>$('#toast').style.display='none',4500); }
function log(text, actor='Ops') { state.events.unshift([text, `Oct 8, 11:05a · ${actor}`]); }
function render() { window.PlanDocument.render(); }
function overviewView() {
  return `<div class="container"><div class="section-head"><div><h2>Build on the incident system we have</h2><p>Add medical recovery state, enforce it in the backend, and reuse cancellation and outreach.</p></div>${badge('Architecture proposal')}</div>
  <div class="cards"><div class="card"><div class="eyebrow">DATA MODEL</div><div class="metric">${PLAN.tables.length} <span style="font-size:13px;font-weight:400">new tables</span></div><p>Cases, submissions, events, shift impacts, notices, consent and durable effects.</p><button class="space-top" data-view="model">See every field →</button></div><div class="card"><div class="eyebrow">LOGIC & DATA</div><div class="metric">${PLAN.flows.length} <span style="font-size:13px;font-weight:400">complete flows</span></div><p>Injury recovery, full clearance, optional illness details, and execution failures.</p><button class="space-top" data-view="flow">Trace reads and writes →</button></div><div class="card"><div class="eyebrow">PRODUCT PREVIEW</div><div class="metric">${window.PROTOTYPE.surfaces.length} <span style="font-size:13px;font-weight:400">connected surfaces</span></div><p>Worker input reaches Ops review. A sent notice appears in the business console.</p><button class="space-top primary" data-view="worker">Start with worker app →</button></div></div>
  <div class="split space-top"><div class="card"><div class="eyebrow">REUSE</div><h3 class="space-top">Keep the existing services in charge</h3>${[['Incident + supervisor intake','Reports, worker/shift/company links and Slack routing'],['WorkerShift cancellation','Cancellation side effects and policy-based backfill'],['Outreach + scheduled jobs','Push/SMS delivery, suppression, timing and audit'],['Ops Action Center patterns','Queue filters, review actions and detail navigation']].map((x,i)=>`<div class="list-row"><span class="number">${i+1}</span><div><h4>${x[0]}</h4><p>${x[1]}</p></div>${badge('Existing','green')}</div>`).join('')}</div><div class="card"><div class="eyebrow">NET NEW</div><h3 class="space-top">Give medical recovery one owner</h3>${[['Medical case lifecycle','One record for injury or illness; in-place conversion'],['Derived booking hold','All open injuries count; account restrictions remain'],['Private medical-note review','Immutable inputs, current-note decisions and consent'],['Safe customer notices','Preview, explicit send and recorded delivery outcome']].map((x,i)=>`<div class="list-row"><span class="number">${i+1}</span><div><h4>${x[0]}</h4><p>${x[1]}</p></div>${badge('New')}</div>`).join('')}</div></div>
  <div class="tint space-top"><h3>Expected return date is a check-in date, not clearance</h3><p style="margin-top:6px">An injury stays blocked until Ops approves full clearance. Clearing one case never clears another injury, suspension or termination.</p></div>
  <div class="split space-top"><div class="card"><h3>Architecture choices</h3><ul class="bullets">${PLAN.decisions.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><div class="card"><h3>Decisions to settle before implementation</h3><ul class="bullets">${PLAN.questions.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div></div>
  <div class="card space-top"><h3>Build sequence</h3><div class="list-row"><span class="number">1</span><div><h4>Case + hold + release path together</h4><p>Schema, confirmed intake, all-path booking enforcement, cancellation, baseline worker upload and Ops review/approve/void. Gate live holds until the full release path works.</p></div></div><div class="list-row"><span class="number">2</span><div><h4>Worker inputs + private review</h4><p>Richer home/history/restriction inputs, optional sick details and medical permissions.</p></div></div><div class="list-row"><span class="number">3</span><div><h4>Follow-ups + customer communication</h4><p>Timers, reminders, claims, preview/send, business notices, document consent and illness conversion.</p></div></div></div>
  <div class="card space-top"><h3>Grounded in the current code</h3><p>Source inspection at Traba commit <code>c60d232e91</code>. Worker mobile layouts are proposed; its source was not available in the inspected workspace.</p><div class="source-list space-top">${PLAN.sources.map(([label,path])=>`<div>${esc(label)} <span class="muted source-link">${esc(path)}</span></div>`).join('')}</div></div></div>`;
}
const workerScreens = [['home','Home & booking','Persistent task and the reason booking is paused'],['upload','Doctor’s note','File, clearance, restrictions and expected return'],['outcome','Submission result','Confirmed shifts, review and the next check-in'],['history','Recovery history','Notes, review reasons and previous decisions'],['sick','Optional sick details','After cancellation; the worker can skip'],['consent','Document sharing','One illness note, one named business'],['faq','Injury help','Short answers and a path to support']];
function workerView() {
  return `<div class="phone-layout"><div class="phone"><div class="phone-status"><span>9:41</span><span>◔ &nbsp; ▰</span></div><div class="phone-top"><strong>${workerScreen==='home'?'traba':'Return to work'}</strong><button data-screen="${workerScreen==='home'?'faq':'home'}" aria-label="${workerScreen==='home'?'Recovery help':'Return to home'}" style="border:0;padding:2px 4px;font-size:11px">${workerScreen==='home'?'Help':'← Home'}</button></div><div class="phone-body">${workerBody()}</div><div class="phone-bottom">${[['home','Home'],['calendar','Shifts'],['chat','Messages'],['user','Profile']].map(([i,l])=>`<div class="${i==='home'?'active':''}">${icon(i)}${l}</div>`).join('')}</div></div>
  <aside class="walkthrough"><div class="eyebrow">WORKER APP</div><h2>Recovery, one step at a time</h2><p>Start with a scenario above, then move through the screens. Submit a note and open Ops console to review the same case.</p>${workerScreens.map(([id,title,desc],i)=>`<button class="screen ${workerScreen===id?'active':''}" data-screen="${id}"><span class="number">${i+1}</span><div>${title}<p>${desc}</p></div></button>`).join('')}<div class="booking-state">${badge(canBook()?'Can book':'Booking paused',canBook()?'green':'orange')}<p>${esc(holdCopy())}. ${state.kind==='illness'?'An illness date only adds a reminder.':''}</p></div><p class="surface-footnote">The worker app receives its own task, note and shift outcomes. Claim details and internal Ops discussions stay in Ops.</p></aside></div>`;
}
function workerBody() {
  const first = state.workerName.split(' ')[0];
  if(workerScreen==='home') return `<div class="phone-row"><div class="eyebrow">THURSDAY, OCTOBER 8</div><span>${badge('Traba temp')}</span></div><h2 style="margin-top:10px">Hi, ${esc(first)}</h2><p style="margin:4px 0 20px">Here’s what’s next.</p>
    ${hasHold()?`<div class="tint orange"><div class="eyebrow">RETURN TO WORK</div><h3 style="margin-top:8px">${state.status==='review'?'Your note is being reviewed':state.otherCase&&state.status==='cleared'?'One more injury needs clearance':'Let’s help you return safely'}</h3><p style="margin-top:8px">${state.status==='review'?'Our team will confirm within 1 business day. Booking stays paused until you’re cleared.':state.status==='restricted'?`Your next check-in is ${shortDate()}. You’ll need a full-clearance note before working again.`:state.otherCase&&state.status==='cleared'?'This case is cleared. Your other injury case is still open.':'Upload your doctor’s note after your visit. Your upcoming shifts are paused while you recover.'}</p><button class="primary full" data-screen="${state.status==='review'?'history':'upload'}">${state.status==='review'?'View submitted note':'Upload doctor’s note'}</button></div>`:state.accountRestricted?`<div class="tint orange"><h3>Your injury case is cleared</h3><p style="margin-top:8px">A separate account restriction still pauses booking. Contact support for help with your account.</p><button class="primary full" data-screen="faq">Get help</button></div>`:`<div class="tint green"><h3>${state.kind==='illness'?'Your return date is noted':'You’re cleared to return'}</h3><p style="margin-top:8px">${state.kind==='illness'?`You expect to return ${shortDate()}. You can still browse and book shifts.`:'You can book shifts again. Previously cancelled shifts are not rebooked automatically.'}</p><button class="primary full" data-action="book">Explore shifts</button></div>`}
    <div class="phone-row space-top"><h3>Upcoming shifts</h3><span>${state.impacts.length} shifts</span></div>${state.impacts.map(s=>shiftCard(s)).join('')}<button class="ghost" style="width:100%" data-action="book">Try booking a new shift</button><button style="border:0;width:100%;margin-top:8px;font-size:11px;color:var(--violet)" data-screen="faq">Questions about your recovery?</button>`;
  if(workerScreen==='upload') return `<div class="eyebrow">YOUR MEDICAL UPDATE</div><h2 style="margin:8px 0">Upload your doctor’s note</h2><p>Your note is private to you and the Traba team reviewing your return to work.</p><form id="note-form" class="space-top"><div class="upload-zone">${icon('file')}<h4>${state.document?esc(state.fileName):'Photo or PDF'}</h4><p>Choose a clear photo or a PDF of your note.</p><input type="file" id="note-file" accept="image/jpeg,image/png,image/heic,application/pdf" aria-label="Doctor’s note file"><button type="button" data-action="sample-file" style="margin-top:10px">Use sample note</button></div><div class="form-field"><label for="visit-date">Doctor visit date</label><input id="visit-date" name="visitDate" type="date" value="2026-10-08" max="2026-10-08" required></div><div class="form-field"><label for="clearance-type">What does your note say?</label><select id="clearance-type" name="clearanceType"><option value="FULL" ${state.clearanceType==='FULL'?'selected':''}>Fully cleared to work</option><option value="RESTRICTED" ${state.clearanceType==='RESTRICTED'?'selected':''}>Cleared with restrictions</option><option value="NOT_CLEARED" ${state.clearanceType==='NOT_CLEARED'?'selected':''}>Not cleared to work</option></select></div><div id="restriction-fields" ${state.clearanceType==='FULL'?'hidden':''}><div class="form-field"><label for="rtw-date">Expected return date</label><input id="rtw-date" type="date" name="expectedDate" min="2026-10-08" value="${state.expectedDate}"><label class="check" style="margin-top:10px"><input type="checkbox" name="dateUnknown" id="date-unknown">My doctor hasn’t given me a date yet</label></div><h4>Restrictions listed in your note</h4><div class="kv"><div><label for="lifting">Lifting limit, lbs</label><input id="lifting" name="lifting" type="number" min="1" placeholder="e.g. 20"></div><div><label for="standing">Standing limit, hours</label><input id="standing" name="standing" type="number" min="0.25" max="24" step="0.25" placeholder="e.g. 2"></div></div>${[['motion','No repetitive motion'],['heights','No ladders or heights'],['machinery','No machinery']].map(([id,l])=>`<label class="check" style="margin:12px 0"><input type="checkbox" name="${id}">${l}</label>`).join('')}<div class="form-field"><label for="other">Other restrictions</label><textarea id="other" name="restrictions" placeholder="Add what your note says"></textarea></div><div class="tint orange"><p>You’ll need another doctor visit and a full-clearance note before returning to work.</p></div></div><button class="primary full" type="submit">Submit note</button></form>`;
  if(workerScreen==='outcome') return `<div class="eyebrow">UPDATE RECEIVED</div><h2 style="margin:8px 0">${state.status==='review'?'We’re reviewing your note':state.kind==='illness'?'Your details are saved':state.status==='cleared'?'You’re cleared to work':'Thanks for your update'}</h2><div class="tint ${state.status==='cleared'?'green':'blue'} space-top"><h3>${state.status==='review'?'You’ll hear from us within 1 business day':state.kind==='illness'?'Your cancellation is already confirmed':`Next check-in: ${state.expectedDate?shortDate():'Oct 22, 2026'}`}</h3><p style="margin-top:8px">${state.status==='review'?'Please wait for our confirmation before taking a shift.':state.kind==='illness'?'Adding these details does not block booking. We’ll keep your expected return date with the absence.':'Before returning, upload a note that fully clears you. We’ll send a check-in by text and push notification.'}</p></div><h3 class="space-top">Your shifts</h3>${state.impacts.map(s=>shiftCard(s)).join('')}${state.cancelPending?`<div class="pending-note">Some cancellations are still processing. We’ll update this list when they’re confirmed.</div>`:''}<button class="primary full" data-screen="home">Back to home</button>`;
  if(workerScreen==='history') return `<div class="eyebrow">${state.caseId} · ${state.kind==='injury'?'INJURY':'ILLNESS'}</div><h2 style="margin:8px 0">Your recovery updates</h2>${badge(statusLabel(),state.status==='cleared'?'green':'orange')}<div class="card space-top"><h3>${state.document?'Doctor’s note · Oct 8':'No doctor’s note yet'}</h3><p>${state.document?esc(state.fileName):'Upload a note after your visit.'}</p>${state.document?`<div class="line"></div><p>${state.clearanceType==='FULL'?'Full clearance':state.clearanceType==='RESTRICTED'?'Restricted clearance':'Not cleared'}</p><p style="margin-top:5px">${state.reviewDecision||'Awaiting next step'}</p>`:''}${state.rejectedReason?`<div class="tint orange space-top"><h4>From the review team</h4><p style="margin-top:6px">${esc(state.rejectedReason)}</p></div>`:''}</div><div class="space-top">${state.events.filter(([text])=>!text.includes('customer notice')&&!text.includes('claim')).map(([text,date])=>`<div class="timeline-item">${esc(text)}<small>${esc(date)}</small></div>`).join('')}</div><button class="primary full" data-screen="upload" ${state.status==='cleared'?'disabled':''}>Upload a new note</button>`;
  if(workerScreen==='sick') return `<div class="eyebrow">CANCELLATION CONFIRMED</div><h2 style="margin:8px 0">Feel better soon</h2><p>Your Oct 9 shift is cancelled. If you have a doctor’s note or know when you’ll be back, you can add it here.</p><div class="tint blue space-top"><p>This step is optional. You can add details later from the cancelled shift.</p></div><form id="illness-form"><div class="form-field"><label for="illness-date">Expected return date</label><input type="date" id="illness-date" name="expectedDate" min="2026-10-08" value="${state.expectedDate}"></div><div class="form-field"><label>Doctor’s note, optional</label><div class="upload-zone"><p>${state.document?esc(state.fileName):'Photo or PDF'}</p><input type="file" id="illness-file" aria-label="Optional illness note" accept="image/jpeg,image/png,application/pdf"><button type="button" data-action="sample-illness" style="margin-top:10px">Use sample note</button></div></div><div class="form-field"><label for="illness-text">Anything you’d like Traba to know?</label><textarea id="illness-text" name="workerNote" placeholder="Optional note for our team"></textarea></div><h4>Other shifts before your return date</h4><p style="margin:5px 0 12px">Only the shifts you select will be cancelled.</p>${state.impacts.slice(1).map((s,i)=>`<label class="check" style="margin:12px 0"><input type="checkbox" name="extraShift" value="${i+1}">${esc(s.label)}<br>Warehouse A · Newark</label>`).join('')}<button class="primary full" type="submit">Save optional details</button><button type="button" data-action="skip-illness" style="border:0;width:100%;font-size:11px;margin-top:8px">Skip for now</button></form>`;
  if(workerScreen==='consent') return `<div class="eyebrow">YOU CONTROL SHARING</div><h2 style="margin:8px 0">Share an illness document</h2><p>The absence notice can say a note is on file without sharing the note itself.</p>${state.kind!=='illness'?`<div class="tint blue space-top"><h3>Injury notes stay private</h3><p style="margin-top:8px">Your injury documents are available only to you and authorized Traba reviewers.</p></div>`:!state.document?`<div class="empty space-top"><h3>No document to share</h3><p>Add an optional illness note first.</p><button class="space-top" data-screen="sick">Add a note</button></div>`:`<div class="card space-top"><div class="eyebrow">THIS DOCUMENT</div><h3 style="margin-top:6px">${esc(state.fileName)}</h3><p>Uploaded Oct 8, 2026</p><div class="line"></div><div class="eyebrow">THIS BUSINESS</div><h3 style="margin-top:6px">Warehouse A · Newark</h3><p>Authorized members of this business can view this file.</p></div><div class="tint orange space-top"><p>You can stop future access at any time. A file already downloaded cannot be taken back. New notes stay private until you choose to share them.</p></div>${state.consent?`<div class="space-top">${badge('Access granted','green')}</div><button class="primary full" data-action="revoke-consent">Stop document access</button>`:`<form id="consent-form" class="space-top"><label class="check"><input type="checkbox" required name="consent">I agree to share this specific document with Warehouse A.</label><button class="primary full" type="submit">Share this document</button></form>`}`}`;
  return `<div class="eyebrow">INJURY & RECOVERY HELP</div><h2 style="margin:8px 0">We’re here to help</h2><p>Get answers about your note, shifts and return to work.</p><div class="faq space-top">${[['When can I work again?','For an injury, Traba needs to approve a note that fully clears you. An expected return date is a check-in date, not approval.'],['What if I don’t have a return date?','Choose “My doctor hasn’t given me a date yet.” We’ll check in after 14 days. Booking stays paused for an injury.'],['Will cancelled shifts affect my record?','Medical cancellations use an exemption. Your shift list shows when the exemption has completed. A sickness cancellation without a note follows the current cancellation policy.'],['Can my business see my medical note?','Injury notes stay private. For illness, the business gets a brief absence notice. Sharing the document itself requires your explicit consent.'],['I’m cleared, but booking is still paused. Why?','Another open injury or account restriction may still apply. Contact Traba for help.']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div><button class="primary full" data-action="help">Ask Traba support</button><p style="margin-top:10px;color:var(--muted)">For an immediate emergency, contact local emergency services.</p>`;
}
function shiftCard(s) { return `<div class="phone-shift"><div class="phone-row"><strong>${esc(s.label)}</strong>${badge(s.status,s.status==='Cancelled'?'orange':s.status==='Booked'?'green':'blue')}</div><p>${esc(s.role)} · Warehouse A, Newark</p>${s.status==='Cancelled'?`<p>${state.exemptionPending?'Medical exemption pending':state.kind==='injury'||state.document?'Medical exemption applied':'Current cancellation policy applies'}</p>`:''}</div>`; }
function sidebar(surface) {
  const ops = surface==='ops';
  return `<aside class="sidebar"><div class="sidebar-logo">traba</div><div class="eyebrow">${ops?'OPERATIONS':'WAREHOUSE A'}</div>${(ops?['Control center','Action Center','Workers','Shifts','Companies','Neutron']:['Dashboard','Shifts','Workers','Messages','Billing']).map(x=>`<div class="nav-item ${x===(ops?'Action Center':'Workers')?'selected':''}">${x}</div>`).join('')}<div class="eyebrow">${ops?'ACTION CENTER':'WORKER MANAGEMENT'}</div>${(ops?['Timesheets','Worker claims','Terminations','Injury & recovery']:['Worker roster','Absences & return']).map(x=>`<div class="nav-item ${x===(ops?'Injury & recovery':'Absences & return')?'selected':''}">${x}</div>`).join('')}</aside>`;
}
function opsView() {
  return `<div class="surface"><div class="desktop-shell">${sidebar('ops')}<div class="desktop-main"><div class="app-bar"><span>Action Center <span class="muted">/ Injury & recovery</span></span><span class="muted">Elise K. · Ops</span></div><div class="desktop-content"><div class="section-head"><div><h2>Injury & recovery</h2><p>Review notes, track claims and help workers return safely.</p></div><button class="primary" data-action="report-injury">Report injury</button></div><div class="stats-strip">${[['OPEN CASES','12'],['PENDING REVIEW',state.status==='review'?'4':'3'],['PAST SLA','1'],['CLAIM NOT FILED','5']].map(([l,v])=>`<div><div class="eyebrow">${l}</div><div class="metric">${v}</div></div>`).join('')}</div><div class="toolbar"><input id="queue-search" placeholder="Search worker or case" aria-label="Search recovery queue"><select id="queue-filter" aria-label="Filter recovery cases"><option value="all">All recovery cases</option><option value="review">Pending review</option><option value="injury">Injuries</option><option value="illness">Illness absences</option></select><span class="right filter-label">Sample queue · 4 records</span></div>
  <div class="queue-layout"><div><div class="table-wrap" style="border:1px solid var(--line);border-radius:8px"><table><thead><tr><th>Worker / case</th><th>State</th><th>Expected return</th><th>Review</th></tr></thead><tbody id="queue-rows">${queueRows()}</tbody></table></div><div id="queue-empty" class="empty hide space-top"><h3>No matching cases</h3><p>Try another worker name or status.</p></div><div class="tint blue space-top"><h3>Medical and account status are separate</h3><p style="margin-top:8px">${esc(state.workerName)} · ${holdCopy()}. ${state.otherCase?'Case MC-1037 still needs clearance.':state.accountRestricted?'Account status remains suspended.':'No unrelated account restriction in this scenario.'}</p></div><div class="card space-top"><div class="section-head"><h3>Impacted shifts</h3><span class="muted" style="font-size:10px">Warehouse A · Newark</span></div>${state.impacts.map(s=>`<div class="list-row"><div><h4>${esc(s.label)}</h4><p>${esc(s.role)}</p></div><span class="right">${badge(s.status,s.status==='Cancelled'?'orange':'blue')}</span></div>`).join('')}${state.cancelPending||state.exemptionPending?`<div class="pending-note space-top">Cancellation or exemption work is still pending. <button data-action="finish-cancel" style="font-size:10px">Complete demo processing</button></div>`:''}</div></div><div class="case-detail"><div class="section-head"><div><div class="eyebrow">${state.caseId} · ${state.kind.toUpperCase()}</div><h2 style="margin-top:6px">${esc(state.workerName)}</h2></div>${badge(statusLabel(),state.status==='cleared'?'green':'orange')}</div><p style="font-size:11px;color:var(--muted)">Warehouse A · Newark · Reported Oct 8</p><div class="subtabs">${[['note','Note'],['claim','Claim'],['timeline','Timeline']].map(([id,label])=>`<button data-ops-tab="${id}" class="${id===opsTab?'active':''}">${label}</button>`).join('')}</div>${opsDetail()}</div></div></div></div></div><p class="surface-footnote">This is a proposed Action Center surface. Queue counts and other workers are sample records; case actions update the connected worker and business previews.</p></div>`;
}
function queueRows() {
  const records = [{name:state.workerName,id:state.caseId,kind:state.kind,status:state.status,label:statusLabel(),date:shortDate(),review:state.status==='review'?'Due Oct 9':'—',selected:true},{name:'James Wilson',id:'MC-1039',kind:'injury',status:'review',label:'Pending review',date:'Oct 10, 2026',review:'Past SLA',scenario:'review'},{name:'Ana Santos',id:'MC-1036',kind:'injury',status:'restricted',label:'Recovering',date:'Oct 16, 2026',review:'—',scenario:'restricted'},{name:'Daniel Kim',id:'MC-1034',kind:'illness',status:'illness',label:'Illness · Open',date:'Oct 12, 2026',review:'—',scenario:'illness'}];
  return records.map(r=>`<tr class="click-row ${r.selected?'selected':''}" data-kind="${r.kind}" data-status="${r.status}" data-search="${esc((r.name+' '+r.id).toLowerCase())}"><td><div class="worker-name"><span class="avatar">${r.name.split(' ').map(x=>x[0]).slice(0,2).join('')}</span><div><strong>${esc(r.name)}</strong><small>${r.id} · Traba temp</small><button style="font-size:9px;border:0;padding:0;color:var(--violet);background:transparent" ${r.selected?'data-action="open-main"':`data-record="${esc(r.name)}" data-record-scenario="${r.scenario}" data-record-id="${r.id}"`}>Open case</button></div></div></td><td>${badge(r.label,r.status==='cleared'?'green':r.kind==='illness'?'blue':'orange')}</td><td>${esc(r.date)}</td><td>${r.review==='Past SLA'?badge(r.review,'red'):r.review}</td></tr>`).join('');
}
function opsDetail() {
  if(opsTab==='timeline') return `<div>${state.events.map(([text,date])=>`<div class="timeline-item">${esc(text)}<small>${esc(date)}</small></div>`).join('')}</div><div class="line"></div><h3>Customer notices</h3>${state.notices.length?state.notices.map(n=>`<div class="list-row"><div><h4>${n.kind==='clearance'?'Clearance notice':'Absence notice'}</h4><p>${esc(n.sentAt)} · supervisor@warehouse.example</p></div>${badge('Sent','green')}</div>`).join(''):`<p style="font-size:11px;margin-top:8px">No customer notice sent yet.</p>`}`;
  if(opsTab==='claim') return state.kind==='illness'?`<div class="tint blue"><h3>No insurance claim for illness</h3><p style="margin-top:8px">If Ops confirms a work-related cause, convert this record into an injury case.</p></div><button class="primary space-top" data-action="convert">Convert to injury</button>`:`<form id="claim-form"><div class="form-field"><label for="claim-status">Claim status</label><select name="claimStatus" id="claim-status">${['Not filed','Filed','Under review','Approved','Denied','Closed'].map(x=>`<option ${state.claimStatus===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="form-field space-top"><label for="claim-number">Claim number</label><input name="claimNumber" id="claim-number" value="${esc(state.claimNumber)}" placeholder="e.g. WC-2026-1042"></div><div class="form-field space-top"><label for="carrier">Carrier</label><input name="carrier" id="carrier" value="${esc(state.carrier)}" placeholder="Carrier name"></div><div class="form-field space-top"><label for="claim-date">Date filed</label><input name="claimFiledAt" type="date" id="claim-date" value="${state.claimFiledAt}" max="2026-10-08"></div><button type="submit" class="primary space-top">Save claim details</button></form><div class="tint blue space-top"><p>Claim status does not change medical clearance or booking eligibility.</p></div>`;
  return `${state.document?`<div class="doc"><div class="stamp">SAMPLE DOCUMENT · PRIVATE PREVIEW</div><h4>${state.kind==='illness'?'Absence document':'Return-to-work note'}</h4><p>Worker: ${esc(state.workerName)}</p><p>Visit: ${esc(shortDate(state.visitDate))}</p><div class="line"></div><p>${state.clearanceType==='FULL'?'Full clearance stated':state.clearanceType==='RESTRICTED'?'Restricted clearance stated':'Not cleared to work'}</p>${state.clearanceType!=='FULL'?state.restrictions.map(r=>`<p>${esc(r)}</p>`).join(''):''}<p style="margin-top:22px;color:var(--muted)">Fictional note used only for product review.</p></div>`:`<div class="empty"><div class="empty-icon">${icon('file')}</div><h3>No note uploaded</h3><p>${state.kind==='injury'?'Worker has a return-to-work task.':'Illness details are optional.'}</p></div>`}
  <div class="kv"><div><div class="eyebrow">WORKER INPUT</div><p>${state.document?(state.clearanceType==='FULL'?'Full clearance':state.clearanceType==='RESTRICTED'?'Restricted':'Not cleared'):'Not submitted'}</p></div><div><div class="eyebrow">EXPECTED RETURN</div><p>${state.document&&state.clearanceType==='FULL'?'Full clearance submitted':shortDate()}</p></div></div>
  ${state.kind==='illness'?`<div class="tint blue"><p>Booking is available. Expected return is a worker-reported date.</p></div><div class="buttons space-top"><button class="primary" data-action="preview-absence">Preview absence notice</button><button data-action="convert">Convert to injury</button></div>`:state.status==='review'?`<div class="tint orange"><p>Review due Oct 9. Approval removes this case’s medical hold.</p></div><div class="buttons space-top"><button class="primary" data-action="approve">Approve clearance</button><button class="danger" data-action="reject">Reject</button><button data-action="request-info">Request more info</button></div>`:state.status==='cleared'?`<div class="tint ${canBook()?'green':'orange'}"><h3>Case cleared</h3><p style="margin-top:6px">${canBook()?'The worker can book again. Review the customer notice before sending.':holdCopy()+'. A return-to-work notice is unavailable until the remaining restriction is resolved.'}</p></div><button class="primary space-top" data-action="preview-clearance" ${!canBook()?'disabled':''}>Preview clearance notice</button>`:`<div class="tint orange"><p>${state.status==='restricted'?`Follow-up planned for ${shortDate()}. Full clearance is still required.`:'Waiting for a current full-clearance note.'}</p></div><div class="buttons space-top"><button data-action="request-update">Request worker update</button><button data-action="void" class="danger">Void false report</button></div>`}
  ${state.rejectedReason?`<div class="pending-note space-top">Last review: ${esc(state.rejectedReason)}</div>`:''}`;
}
function businessView() {
  const notices = state.notices;
  return `<div class="surface"><div class="desktop-shell">${sidebar('business')}<div class="desktop-main"><div class="app-bar"><span>Workers <span class="muted">/ Absences & return</span></span><span class="muted">Warehouse A · Newark</span></div><div class="desktop-content"><div class="section-head"><div><h2>Absences & return</h2><p>Updates from Traba about your workers and upcoming shifts.</p></div>${badge('Warehouse A','blue')}</div><div class="split"><div><div class="card"><div class="worker-name"><span class="avatar">${state.workerName.split(' ').map(x=>x[0]).slice(0,2).join('')}</span><div><h3>${esc(state.workerName)}</h3><p style="font-size:11px">Traba temp · Picker / packer</p></div></div><div class="line"></div><div class="kv"><div><div class="eyebrow">AVAILABILITY</div><p>${canBook()?'Available for future shifts':'Currently unavailable'}</p></div><div><div class="eyebrow">LATEST UPDATE</div><p>${notices.length?notices[notices.length-1].kind==='clearance'?'Cleared Oct 8':`Expected ${notices[notices.length-1].date}`:'No new notice from Traba'}</p></div></div>${state.kind==='illness'&&notices.some(n=>n.kind==='absence')?`<div class="tint blue"><p>Expected return is provisional. Traba will share any updates.</p></div>`:''}</div><div class="card space-top"><h3>Affected shifts at your facility</h3>${state.impacts.map(s=>`<div class="list-row"><div><h4>${esc(s.label)}</h4><p>${s.status==='Cancelled'?'Traba is handling replacement coverage':s.status==='Booked'?'Worker remains booked':'Traba is reviewing coverage'}</p></div><span class="right">${badge(s.status==='Needs Ops review'?'Coverage review':s.status,s.status==='Booked'?'green':'orange')}</span></div>`).join('')}</div></div><div><div class="section-head"><h3>Traba notices</h3>${badge(`${notices.length} sent`,'blue')}</div>${notices.length?notices.slice().reverse().map(n=>`<article class="notice"><div class="phone-row">${badge(n.kind==='clearance'?'Return to work':'Absence update',n.kind==='clearance'?'green':'blue')}<span>Oct 8</span></div><h3>${esc(n.workerName)} ${n.kind==='clearance'?'is cleared to return':'is out sick'}</h3><p>${n.kind==='clearance'?`${esc(n.workerName)} has been medically cleared and can return to work starting ${esc(n.date)}.`:`${esc(n.workerName)} is out sick for the affected shifts listed and expects to return ${esc(n.date)}. A doctor’s note is ${n.documentOnFile?'on file':'not provided'}.`}</p><small>Sent by Traba · ${esc(n.sentAt)} · supervisor@warehouse.example</small></article>`).join(''):`<div class="empty"><div class="empty-icon">${icon('chat')}</div><h3>No new absence or return notice</h3><p>Updates will appear here after Traba reviews and sends them.</p></div>`}
  ${state.kind==='illness'&&state.consent&&state.document?`<div class="notice space-top"><div class="eyebrow">SHARED BY THE WORKER</div><h3>Authorized absence document</h3><p>${esc(state.workerName)} gave Warehouse A access to one document.</p><button data-action="view-authorized" class="space-top">View authorized document</button></div>`:''}<div class="tint blue space-top"><h3>Private information stays with the worker</h3><p style="margin-top:8px">These updates include affected shifts and return dates. Medical details are not included. A worker may separately choose to share an illness document.</p></div></div></div></div></div></div><p class="surface-footnote">Business receives only company-scoped availability and sent notice fields. No claim status, restrictions, injury document links or internal history appear here.</p></div>`;
}
function openModal(html) { const modal = $('#modal'); modal.innerHTML = html; modal.showModal(); }
function noticePreview(kind) {
  if(kind==='clearance'&&!canBook()) return toast('Another restriction prevents a return-to-work notice.');
  const date = kind==='clearance'?'Oct 8, 2026':shortDate();
  openModal(`<div class="eyebrow">PREVIEW BEFORE SENDING</div><h2>${kind==='clearance'?'Clearance notice':'Absence notice'}</h2><p>To supervisor@warehouse.example · Warehouse A, Newark</p><div class="preview-message"><strong>${esc(state.workerName)} · ${kind==='clearance'?'Return to work':'Absence update'}</strong><p>${kind==='clearance'?`${esc(state.workerName)} has been medically cleared and can return to work starting ${date}.`:`${esc(state.workerName)} is out sick for ${state.impacts.filter(s=>s.status==='Cancelled').map(s=>s.label.split(' · ')[0]).join(', ')} and expects to return ${date}. A doctor’s note is ${state.document?'on file':'not provided'}.`}</p></div><p style="margin-top:14px;color:var(--muted)">This notice does not attach a medical document or include diagnosis, restrictions or worker notes.</p><div class="buttons"><button data-action="close-modal">Back</button><button class="primary" data-action="send-notice" data-kind="${kind}">Send notice</button></div>`);
}
function filterQueue() {
  const query = ($('#queue-search')?.value || '').toLowerCase(), filter = $('#queue-filter')?.value || 'all'; let count=0;
  document.querySelectorAll('#queue-rows tr').forEach(row=>{const shown=row.dataset.search.includes(query)&&(filter==='all'||(filter==='review'?row.dataset.status==='review':row.dataset.kind===filter)); row.hidden=!shown; if(shown)count++;});
  $('#queue-empty')?.classList.toggle('hide',count>0);
}
document.addEventListener('click',event=>{
  const button = event.target.closest('button'); if(!button||button.disabled)return;
  if(button.dataset.screen){workerScreen=button.dataset.screen;render();return;}
  if(button.dataset.opsTab){opsTab=button.dataset.opsTab;render();return;}
  if(button.dataset.record){const name=button.dataset.record,id=button.dataset.recordId,s=button.dataset.recordScenario;loadScenario(s);state.workerName=name;state.caseId=id;render();return;}
  const action=button.dataset.action;
  if(action==='book'){if(!canBook())toast(holdCopy()+'. Booking stays paused.');else if(state.kind==='illness')openModal(`<h2>A quick reminder</h2><p>You told us you expect to return ${shortDate()}. This shift is before that date.</p><div class="buttons"><button data-action="close-modal">Go back</button><button class="primary" data-action="continue-booking">Continue booking</button></div>`);else toast('Booking is available. Cancelled shifts will not be rebooked automatically.');}
  if(action==='continue-booking'){$('#modal').close();toast('You can continue booking under the ordinary shift eligibility rules.');}
  if(action==='sample-file'||action==='sample-illness'){state.document=true;state.fileName=action==='sample-illness'?'absence-note.pdf':'medical-note.pdf';render();toast('Sample note selected.');}
  if(action==='approve'){state.impacts.forEach(s=>{if(s.status==='Needs Ops review')s.status='Booked';});state.status='cleared';state.reviewDecision='Approved';state.rejectedReason='';log('Full-clearance note approved · Case resolved');render();toast(canBook()?'Case cleared. Preview the customer notice before sending.':'Case cleared. '+holdCopy()+'.');}
  if(action==='reject'||action==='request-info')openModal(`<h2>${action==='reject'?'Reject note':'Request more information'}</h2><p>The worker will see your reason and can upload a new note. Booking stays paused.</p><form id="review-form" data-decision="${action}"><div class="form-field"><label for="review-reason">Message to the worker</label><textarea id="review-reason" name="reason" required placeholder="Explain what is needed"></textarea></div><div class="buttons"><button type="button" data-action="close-modal">Back</button><button class="primary" type="submit">Confirm ${action==='reject'?'rejection':'request'}</button></div></form>`);
  if(action==='preview-clearance')noticePreview('clearance');
  if(action==='preview-absence')noticePreview('absence');
  if(action==='send-notice'){const kind=button.dataset.kind;if(kind==='clearance'&&!canBook())return toast('A remaining restriction prevents this notice.');if(state.notices.some(n=>n.kind===kind)){$('#modal').close();return toast('This notice has already been sent.');}state.notices.push({kind,workerName:state.workerName,date:kind==='clearance'?'Oct 8, 2026':shortDate(),documentOnFile:state.document,sentAt:'Oct 8, 11:05a'});log(`${kind==='clearance'?'Clearance':'Absence'} customer notice sent`);$('#modal').close();render();toast('Notice sent. It is now visible in Business console.');}
  if(action==='convert')openModal(`<h2>Convert illness to injury?</h2><p>The same case keeps its notes and dates. Booking will pause, active document sharing will stop, and the injury clearance flow will begin.</p><div class="buttons"><button data-action="close-modal">Back</button><button class="primary" data-action="confirm-convert">Convert to injury</button></div>`);
  if(action==='confirm-convert'){state.impacts.forEach((s,i)=>{if(s.status==='Booked')s.status=i===0?'Processing':'Needs Ops review';});state.kind='injury';state.status='reported';state.consent=false;state.claimStatus='Not filed';state.clearanceType='NOT_CLEARED';log('Illness converted to injury · Document consent revoked');$('#modal').close();render();toast('Injury hold started. Existing notes remain in the case.');}
  if(action==='void')openModal(`<h2>Void a false report</h2><p>Use this only when the report should not be an injury case. Cancelled shifts will not be rebooked.</p><form id="void-form"><div class="form-field"><label for="void-reason">Reason</label><textarea id="void-reason" name="reason" required></textarea></div><div class="buttons"><button type="button" data-action="close-modal">Back</button><button type="submit" class="primary">Void case</button></div></form>`);
  if(action==='request-update'){log('Worker update requested','System');toast('Update requested through the worker outreach broker.');render();}
  if(action==='skip-illness'){workerScreen='home';render();toast('Optional details skipped. The shift remains cancelled.');}
  if(action==='revoke-consent'){state.consent=false;log('Illness document access revoked','Worker');render();toast('Future business document access stopped.');}
  if(action==='view-authorized')openModal(`<div class="eyebrow">WORKER-AUTHORIZED DOCUMENT</div><h2>Absence document</h2><div class="doc"><div class="stamp">SAMPLE DOCUMENT · SHARED WITH WAREHOUSE A</div><h4>${esc(state.workerName)}</h4><p>${esc(state.fileName)}</p><p>Fictional illness document preview.</p></div><p>Access is limited to this document and can be revoked by the worker.</p><div class="buttons"><button data-action="close-modal">Close</button></div>`);
  if(action==='help')openModal(`<h2>Contact Traba support</h2><p>This preview proposes a support entry point. The intended worker help bot and mobile integration need verification before implementation.</p><div class="buttons"><button data-action="close-modal">Close</button></div>`);
  if(action==='close-modal')$('#modal').close();
  if(action==='report-injury')openModal(`<h2>Report an injury</h2><p>This action extends existing incident intake. It creates a report first, then a linked recovery case after confirmation.</p><form id="report-form"><div class="form-field"><label>Worker</label><input name="worker" value="${esc(state.workerName)}" required></div><div class="form-field"><label>Incident description</label><textarea name="description" required placeholder="What happened?"></textarea></div><div class="buttons"><button type="button" data-action="close-modal">Back</button><button type="submit" class="primary">Create report and case</button></div></form>`);
  if(action==='finish-cancel'){state.cancelPending=false;state.exemptionPending=false;state.impacts.forEach(s=>{if(s.status==='Processing')s.status='Cancelled';});log('Selected shift cancellations completed','System');render();toast('Shift cancellations confirmed.');}
  if(action==='open-main'){opsTab='note';render();}
});
document.addEventListener('change',event=>{
  if(event.target.id==='clearance-type'){$('#restriction-fields').hidden=event.target.value==='FULL';}
  if(event.target.id==='date-unknown')$('#rtw-date').disabled=event.target.checked;
  if(event.target.id==='queue-filter')filterQueue();
  if(['note-file','illness-file'].includes(event.target.id)&&event.target.files.length){state.document=true;state.fileName=event.target.files[0].name;toast('File selected locally. Nothing is uploaded by this preview.');}
});
document.addEventListener('input',event=>{if(event.target.id==='queue-search')filterQueue();});
document.addEventListener('submit',event=>{
  event.preventDefault();const form=event.target,data=new FormData(form);
  if(form.id==='note-form'){
    if(state.kind!=='injury')return toast('Choose an injury scenario to try this flow.');
    if(['cleared','voided'].includes(state.status))return toast('This injury case is closed.');
    if(!state.document)return toast('Choose a file or use the sample note first.');
    const clearance=data.get('clearanceType'),unknown=data.get('dateUnknown')==='on',expected=data.get('expectedDate');
    if(clearance!=='FULL'&&!unknown&&!expected)return toast('Enter an expected return date or choose that it is not yet known.');
    state.visitDate=data.get('visitDate');state.restrictions=clearance==='FULL'?[]:[data.get('lifting')?`Lifting limit: ${data.get('lifting')} lbs`:'',data.get('standing')?`Standing limit: ${data.get('standing')} hours`:'',data.get('motion')?'No repetitive motion':'',data.get('heights')?'No ladders or heights':'',data.get('machinery')?'No machinery':'',String(data.get('restrictions')||'').trim()].filter(Boolean);
    state.clearanceType=clearance;state.status=clearance==='FULL'?'review':'restricted';state.expectedDate=clearance==='FULL'?state.expectedDate:unknown?'':expected;state.reviewDecision='';state.rejectedReason='';
    if(clearance!=='FULL'){state.impacts.forEach((s,i)=>{const shiftDate=['2026-10-09','2026-10-12','2026-10-20'][i];if(!state.expectedDate||shiftDate<=state.expectedDate)s.status='Cancelled';});}
    log(clearance==='FULL'?'Full-clearance note submitted · Ops review due Oct 9':`Recovery note submitted · Check-in ${state.expectedDate?shortDate():'Oct 22'}`,'Worker');workerScreen='outcome';render();toast('Note submitted. Open Ops console to continue the same case.');
  }
  if(form.id==='illness-form'){
    if(state.kind!=='illness')return toast('Choose the Sick cancellation scenario to try optional illness details.');
    if(!state.document&&!data.get('expectedDate')&&!String(data.get('workerNote')).trim())return toast('Add a note, return date or message, or choose Skip for now.');
    state.expectedDate=data.get('expectedDate');
    const chosen=data.getAll('extraShift').map(Number);chosen.forEach(i=>state.impacts[i].status='Processing');state.cancelPending=chosen.length>0;state.exemptionPending=state.document;
    log('Optional illness details saved'+(state.document?' · Medical exemption requested':''),'Worker');workerScreen='outcome';render();toast('Details saved. Booking remains available.');
  }
  if(form.id==='review-form'){state.status='reported';state.reviewDecision=form.dataset.decision==='reject'?'Rejected':'More information requested';state.rejectedReason=String(data.get('reason')).trim();log(`Note ${state.reviewDecision.toLowerCase()}`);$('#modal').close();render();toast('Review saved. Worker can see the reason and upload another note.');}
  if(form.id==='claim-form'){if(data.get('claimStatus')!=='Not filed'&&!data.get('claimFiledAt'))return toast('Enter the date filed for a filed claim.');state.claimStatus=data.get('claimStatus');state.claimNumber=data.get('claimNumber');state.carrier=data.get('carrier');state.claimFiledAt=data.get('claimFiledAt');log('Insurance claim details updated');render();toast('Claim details saved. Medical clearance is unchanged.');}
  if(form.id==='consent-form'){state.consent=true;log('Illness document access granted to Warehouse A','Worker');render();toast('This one document is available to Warehouse A.');}
  if(form.id==='void-form'){state.impacts.forEach(s=>{if(s.status==='Needs Ops review')s.status='Booked';});state.status='voided';log('False report voided · '+String(data.get('reason')).trim());$('#modal').close();render();toast('Case voided. Cancelled shifts remain cancelled.');}
  if(form.id==='report-form'){const name=String(data.get('worker')).trim();$('#modal').close();loadScenario('reported');state.workerName=name;render();toast('Sample report and injury case created.');}
});

window.PROTOTYPE = {
  surfaces: [{id:'worker',label:'Worker app'},{id:'ops',label:'Ops console'},{id:'business',label:'Business console'}],
  scenarios: [{"id": "reported", "label": "New injury report"}, {"id": "restricted", "label": "Restricted recovery"}, {"id": "review", "label": "Full note awaiting review"}, {"id": "cleared", "label": "Cleared and notified"}, {"id": "illness", "label": "Sick cancellation"}, {"id": "multiple", "label": "Another open injury"}, {"id": "suspended", "label": "Another account restriction"}],
  initialScenario: 'reported',
  init() { loadScenario('reported'); },
  selectScenario: loadScenario,
  reset() { loadScenario(scenario); toast('Demo reset.'); },
  status() { return {label:holdCopy(),tone:canBook()?'green':'orange'}; },
  render(id) { return ({worker:workerView,ops:opsView,business:businessView})[id](); },
  overview: overviewView
};
})();
